// Linux 查看进程虚拟内存布局
// cat /proc/<pid>/maps
// 00400000-00452000 r-xp  00000000 08:02 131074  /usr/bin/cat
// 00651000-00652000 r--p  00051000 08:02 131074  /usr/bin/cat
// 00652000-00653000 rw-p  00052000 08:02 131074  /usr/bin/cat
// 7f8c12345000-7f8c12367000 r-xp  00000000 08:02 262147  /lib/x86_64-linux-gnu/libc-2.31.so
// 7ffe12345000-7ffe12366000 rw-p  00000000 00:00 0       [stack]

// mmap 系统调用示例：创建匿名映射
#include <sys/mman.h>
#include <stdio.h>

int main() {
    // 分配 4KB 虚拟内存（不立即分配物理内存）
    void *addr = mmap(NULL, 4096,
        PROT_READ | PROT_WRITE,
        MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

    if (addr == MAP_FAILED) {
        perror("mmap failed");
        return 1;
    }

    // 首次访问时触发缺页中断，分配物理页
    *(int *)addr = 42;
    printf("Value: %d\n", *(int *)addr);

    munmap(addr, 4096);
    return 0;
}

